def make_symmetric(inp):
    n, m = len(inp), len(inp[0])
    out = [row[:] for row in inp]

    # Process each symmetric group once (top-left quadrant)
    for i in range(n//2):
        for j in range(m//2):
            # Get all 4 symmetric positions
            group = {(i,j), (i,m-1-j), (n-1-i,j), (n-1-i,m-1-j)}

            # Find all non-3 values in input
            vals = {}
            for r,c in group:
                v = inp[r][c]
                if v != 3:
                    vals[v] = True

            if len(vals) == 1:
                val = list(vals.keys())[0]
            elif len(vals) == 0:
                # All 3s - default to something reasonable? 
                # Based on demo, this shouldn't happen or uses some special logic
                val = None
            else:
                val = list(vals.keys())[0]

            # Fill all cells in group with val if any were 3
            if val is not None:
                for r,c in group:
                    if inp[r][c] == 3:
                        out[r][c] = val

    return out

